import{_ as o,o as i,c as l,ae as a}from"./chunks/framework.qNV68s4p.js";const p=JSON.parse('{"title":"排障","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/troubleshooting.md","filePath":"zh/guide/troubleshooting.md","lastUpdated":null}'),t={name:"zh/guide/troubleshooting.md"};function r(d,e,n,c,u,s){return i(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="排障" tabindex="-1">排障 <a class="header-anchor" href="#排障" aria-label="Permalink to &quot;排障&quot;">​</a></h1><p>这一页汇总集成和发布 SweetEditor 时最常见的问题。</p><h2 id="github-pages-显示成普通-markdown-页面" tabindex="-1">GitHub Pages 显示成普通 Markdown 页面 <a class="header-anchor" href="#github-pages-显示成普通-markdown-页面" aria-label="Permalink to &quot;GitHub Pages 显示成普通 Markdown 页面&quot;">​</a></h2><p>原因：</p><ul><li>GitHub Pages 仍在直接发布 branch 或 <code>docs/</code> 目录，而不是 GitHub Actions 构建产物</li></ul><p>修复方式：</p><ol><li>打开仓库 <code>Settings</code></li><li>进入 <code>Pages</code></li><li>将 <code>Build and deployment &gt; Source</code> 切到 <code>GitHub Actions</code></li><li>重新运行 Pages workflow</li></ol><h2 id="首页-hero-图或-logo-不显示" tabindex="-1">首页 Hero 图或 Logo 不显示 <a class="header-anchor" href="#首页-hero-图或-logo-不显示" aria-label="Permalink to &quot;首页 Hero 图或 Logo 不显示&quot;">​</a></h2><p>原因：</p><ul><li>VitePress 首页和站点 logo 使用的是 public 静态资源</li><li>对应图片必须放在 <code>docs/public</code> 下</li></ul><p>修复方式：</p><ul><li>将 hero/logo 图片放到 <code>docs/public/...</code></li><li>使用类似 <code>/snapshot/Screenshot_Desktop.png</code> 的 public 路径</li></ul><h2 id="滚动时-decoration-一直重复追加" tabindex="-1">滚动时 Decoration 一直重复追加 <a class="header-anchor" href="#滚动时-decoration-一直重复追加" aria-label="Permalink to &quot;滚动时 Decoration 一直重复追加&quot;">​</a></h2><p>原因：</p><ul><li>可视区范围型 decoration provider 使用了 <code>DecorationApplyMode.Merge</code></li></ul><p>修复方式：</p><ul><li>对按行、按可见区重算的 decoration，优先使用 <code>DecorationApplyMode.ReplaceRange</code></li></ul><h2 id="completion-不弹" tabindex="-1">Completion 不弹 <a class="header-anchor" href="#completion-不弹" aria-label="Permalink to &quot;Completion 不弹&quot;">​</a></h2><p>检查项：</p><ul><li>是否通过 <code>addCompletionProvider()</code> 注册了 provider</li><li>是否手动触发了 completion，或者 provider 支持触发字符</li><li>当前是否处于 linked editing 等可能冲突的状态</li></ul><h2 id="inline-suggestion-不显示" tabindex="-1">Inline Suggestion 不显示 <a class="header-anchor" href="#inline-suggestion-不显示" aria-label="Permalink to &quot;Inline Suggestion 不显示&quot;">​</a></h2><p>检查项：</p><ul><li>是否调用了 <code>controller.inlineSuggestions().show(...)</code></li><li><code>line</code> 和 <code>column</code> 是否是合法的 0-based 位置</li><li>是否在文档加载完成之后再显示 suggestion</li></ul><h2 id="theme-不生效" tabindex="-1">Theme 不生效 <a class="header-anchor" href="#theme-不生效" aria-label="Permalink to &quot;Theme 不生效&quot;">​</a></h2><p>检查项：</p><ul><li>是否调用了 <code>controller.applyTheme(theme)</code></li><li>是否稳定使用 <code>rememberEditorAppearance()</code> 或 <code>rememberEditorTheme()</code></li><li>行为相关配置是否错误地写进了 themeContent，而不是 <code>EditorSettings</code></li></ul><h2 id="本地构建成功-但线上看起来还是旧站" tabindex="-1">本地构建成功，但线上看起来还是旧站 <a class="header-anchor" href="#本地构建成功-但线上看起来还是旧站" aria-label="Permalink to &quot;本地构建成功，但线上看起来还是旧站&quot;">​</a></h2><p>原因：</p><ul><li>Pages 可能还在使用旧部署</li><li>或者当前仍指向错误的部署来源</li></ul><p>修复方式：</p><ul><li>检查最新 workflow 是否成功</li><li>确认 Pages source 是 <code>GitHub Actions</code></li><li>部署完成后强制刷新页面</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./architecture">架构</a></li><li><a href="./faq">FAQ</a></li><li>英文 <a href="./../../guide/api-cookbook">API Cookbook</a></li></ul>',33)])])}const g=o(t,[["render",r]]);export{p as __pageData,g as default};
